date -u && menv python -c 'from hera.analysis import open_run,resolve_channels,current_channel,sdh_onset; import numpy as np; from scipy.signal import find_peaks
for rid in (6,7):
 r=open_run(f"data/{rid}"); ch=resolve_channels(r.meta); cur=current_channel(ch); v=next(c for c in ch if not c.is_current); I=r.col(cur.col)/cur.gain; R=(r.col(v.col)/v.gain)/I; B=r.col("magnet_field"); order=np.argsort(B); print("RUN",rid,"R range",np.min(R),np.max(R),"I nA",np.min(I)*1e9,np.max(I)*1e9,"T",np.min(r.col("T_sample")),np.max(r.col("T_sample")))
 try:
  a=sdh_onset(R[order],B[order],r_full_scale=5000); print(a.summary())
 except Exception as e: print(type(e).__name__,str(e))
 r5=open_run("data/5"); dt=np.diff(r5.col("time")); print("run5 withinrow timing",np.percentile(dt,[25,50,75,95]))'
